//==================================================================================
// This is an autogenerated file.
// User must drive any custom input ports.
// This TB will not work if you have custom input ports or custom ID.
// Description: Top TB module, drive DUT and monitoring outputs
//    
//==================================================================================

`timescale 1ns/1ps
module {{ module }} ();

logic clk;
logic rst;
{% for port in custom_inputs -%}
logic [{{ port.width - 1 }}:0] {{ port.name }},
{% endfor -%}
logic [{{ comp_din_bits_list[0] - 1 }}:0] data_in;
logic data_in_sop;
logic data_in_eop;
logic data_in_valid;
logic data_in_ready;
logic path_id_out_ready;
logic [{{ lookup_dout_outb_list[-1] }} - 1:0] path_id_out;
logic path_id_out_valid;

// Clock generation
initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
end

// Stimulus vector
logic [{{ stimulus_width }}-1:0] stimulus_vec [0:{{ stimulus_list|length - 1 }}];

initial begin
    stimulus_vec = {
{%- for s in stimulus_list %}
        {{ stimulus_width }}'h{{ s }}{% if not loop.last %},{% endif -%}
{% endfor %}
    };
end

// Golden output queue
logic [{{ lookup_dout_outb_list[-1] }}-1:0] golden_q[$] =  {
{%- for g in golden_list %}
    {{ g }}{% if not loop.last %},{% endif -%}
{% endfor %}
};


//Driving Stimulus to DUT
initial begin
    $dumpfile("{{ module }}.vcd");
    $dumpvars(0, {{ module }});
    rst = 1;
    data_in = '0;
    data_in_valid = '0;
    path_id_out_ready = 1'b1;
    #20;
    rst = 0;
    data_in_sop = '0;
    data_in_eop = '0;

    // Send packets
    for (int ii = 0; ii < {{ stimulus_list|length }}; ii = ii + 1) begin
{% for chunk_idx in range(num_chunks) %}
      @(posedge clk);
      data_in_valid = 1'b1;
      data_in_sop = {{ "1'b1" if chunk_idx == 0 else "1'b0" }};
      data_in_eop = {{ "1'b1" if chunk_idx == num_chunks - 1 else "1'b0" }};
      data_in = stimulus_vec[ii][{{ stimulus_width - 1 - chunk_idx * comp_din_bits_list[0] }} -: {{ comp_din_bits_list[0] }}];
{% endfor %}
      @(posedge clk);
      data_in  = '0;
      data_in_valid = 1'b0;
      data_in_sop = 1'b0;
      data_in_eop = 1'b0;

      // Idle cycles between packets -- generous enough to drain the
      // comparison/lookup pipeline before the next SOP, so a new packet
      // can't reset flit_counter mid-flight and corrupt path_id_out.
      repeat ($urandom_range({{ num_chunks + 2 }}, {{ num_chunks + 5 }})) @(posedge clk);
    end

    // Finish after some time
    #100;
    $finish;
end

// DUT instantiation
hex_to_rtl_top
dut (
    .clk            (clk),
    .rst            (rst),
    {% for port in custom_inputs -%}
    .{{ port.name }} ({{ port.name }} ),
    {% endfor -%}
    .data_in        (data_in),
    .data_in_sop    (data_in_sop),
    .data_in_eop    (data_in_eop),
    .data_in_valid  (data_in_valid),
    .data_in_ready  (data_in_ready),
    .path_id_out_ready (path_id_out_ready),
    .path_id_out    (path_id_out),
    .path_id_out_valid (path_id_out_valid)
);

// Scoreboard
logic [{{ lookup_dout_outb_list[-1] }}-1:0] dut_q[$];

//store the data from dut into dut_q
always_ff @ (posedge clk) begin
    if (path_id_out_valid) begin
        dut_q.push_back(path_id_out);
    end
end

always_ff @ (posedge clk) begin
    if (dut_q.size() > 0 && golden_q.size() > 0) begin
        logic [{{ lookup_dout_outb_list[-1] }}-1:0] act = dut_q.pop_front();
        logic [{{ lookup_dout_outb_list[-1] }}-1:0] exp = golden_q.pop_front();

        if (act != exp) begin
            $display ("[%0t] MISMATCH: Got %0h, Expected %0h", $time, act, exp);
        end else begin
            $display ("[%0t] MATCH: %0h", $time, act);
        end
    end
end

endmodule: {{ module }}

